    bands = []
    start = None
    for r in range(height + 1):
        active = r < height and any(value != background for value in grid[r])
        if active and start is None:
            start = r
        elif not active and start is not None:
            bands.append((start, r))
            start = None
    if len(bands) != 2 or bands[0][1] - bands[0][0] != bands[1][1] - bands[1][0]:
        return out

    pairs = list(zip(range(*bands[0]), range(*bands[1])))
    ends = []
    for ar, br in pairs:
        ae = max((c for c, v in enumerate(grid[ar]) if v != background), default=-1)
        be = max((c for c, v in enumerate(grid[br]) if v != background), default=-1)
        ends.append((ae, be))

    alignments = []
    for shift in range(-4, 5):
        errors = samples = 0
        for (ar, br), (ae, be) in zip(pairs, ends):
            for c in range(width):
                bc = c + shift
                if c <= ae and 0 <= bc < width and bc <= be:
                    samples += 1
                    errors += grid[ar][c] != grid[br][bc]
        alignments.append((errors, -samples, abs(shift), shift))
    shift = min(alignments)[3]

    for (ar, br), (ae, be) in zip(pairs, ends):
